gb6n(){return"\ud55c \uacbd\uae30\ub294 \uc804\ubc18 45\ubd84, \ud6c4\ubc18 45\ubd84\uc73c\ub85c \uc9c4\ud589\ub3fc\uc694.\n\uc870\ubcc4\ub9ac\uadf8\ub294 \ube44\uaca8\ub3c4 \ub05d\ub0a0 \uc218 \uc788\uace0, \ub450 \ud300\uc774 \uc2b9\uc810 1\uc810\uc529 \uac00\uc838\uac00\uc694.\n\ud1a0\ub108\uba3c\ud2b8\uc5d0\uc11c 90\ubd84 \ub3d9\uc548 \ube44\uae30\uba74 \uc5f0\uc7a5\uc804\uc744 \ud558\uace0, \uadf8\ub798\ub3c4 \uac19\uc73c\uba74 \uc2b9\ubd80\ucc28\uae30\ub85c \uc2b9\uc790\ub97c \uc815\ud574\uc694.\n\uc870\ubcc4\ub9ac\uadf8 \uc2b9\uc810\uc740 \uc2b9\ub9ac 3\uc810, \ubb34\uc2b9\ubd80 1\uc810, \ud328\ubc30 0\uc810\uc774\uc5d0\uc694."},
gb6s(){return"\uc21c\uc704\uac00 \uac19\uc744 \ub54c"},
gb6r(){return"\uac00\uc7a5 \uba3c\uc800 \uc2b9\uc810\uc744 \ubd10\uc694.\n\uac19\uc740 \uc870 \uc548\uc5d0\uc11c \uc2b9\uc810\uc774 \uac19\uc73c\uba74 \ub9de\ub300\uacb0 \uc2b9\uc810, \ub9de\ub300\uacb0 \ub4dd\uc2e4\ucc28, \ub9de\ub300\uacb0 \ub4dd\uc810\uc744 \ucc28\ub840\ub85c \ubd10\uc694.\n\uadf8\ub798\ub3c4 \uac19\uc73c\uba74 \uc804\uccb4 \ub4dd\uc2e4\ucc28, \uc804\uccb4 \ub4dd\uc810, \ud300 \ud398\uc5b4\ud50c\ub808\uc774 \uc810\uc218, \ucd5c\uc2e0 FIFA \ub7ad\ud0b9\uc744 \ubd10\uc694.\n3\uc704 \ud300\ub07c\ub9ac\ub294 \uc2b9\uc810, \ub4dd\uc2e4\ucc28, \ub4dd\uc810, \ud300 \ud398\uc5b4\ud50c\ub808\uc774 \uc810\uc218, FIFA \ub7ad\ud0b9 \uc21c\uc11c\ub85c \uc88b\uc740 8\ud300\uc744 \uc815\ud574\uc694."},
