gaUS(){return"\uc774 \ud654\uba74\uc740 \ucd2c\uc601 \uad6c\ub3c4 \uc548\ub0b4\uc608\uc694. \uc790\uc138 \uc810\uc218\uc640 \ucf54\uce6d\uc740 \ub0b4\uac00 \uc5c5\ub85c\ub4dc\ud55c \uc601\uc0c1\uc5d0\uc11c\ub9cc \uacc4\uc0b0\ud574\uc694."},
gaUW(){return"\uc5c5\ub85c\ub4dc \uc804 \ud655\uc778"},
gaUT(){return"\uce74\uba54\ub77c\ub97c \uace0\uc815\ud558\uace0 \ub2ec\ub9ac\ub294 \uc120\uacfc \uc815\ud655\ud788 \uc9c1\uac01\uc73c\ub85c \ub450\uc138\uc694."},
gaUV(){return"\uba38\ub9ac\ubd80\ud130 \uc591\ucabd \uc2e0\ubc1c\uae4c\uc9c0 \uacc4\uc18d \ubcf4\uc774\ub3c4\ub85d, \uc804\uc2e0\uc774 \ud654\uba74 \ub192\uc774\uc758 50~75%\ub97c \ucc28\uc9c0\ud558\uac8c \ub9de\ucd94\uc138\uc694."},
gaUU(){return"\ubc1d\uace0 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc5d0\uc11c 3~6\ubcf4\uac00 \ub2f4\uae34 5~10\ucd08 \uc601\uc0c1\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."},
gaUR(){return"\ubd84\uc11d \uacb0\uacfc\ub294 \ub0b4 \uc601\uc0c1\uc5d0\uc11c\ub9cc"},
gaUQ(){return"\uc774 \uac00\uc774\ub4dc\ub294 \ucd2c\uc601 \ud488\uc9c8\uc744 \ubcf4\uc5ec \uc90d\ub2c8\ub2e4. \uc790\uc138 \uc810\uc218\uc640 \uad50\uc815\uc740 \uc5c5\ub85c\ub4dc\ud55c \ud504\ub808\uc784\uacfc \uc2e0\ub8b0\ub3c4 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud574\uc694."},
